import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.material3.pulltorefresh.PullToRefreshBox
import androidx.compose.runtime.*
import kotlinx.coroutines.delay
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun R(){
  var items by remember{mutableStateOf(List(20){"row $it"})}
  var refreshing by remember{mutableStateOf(false)}
  PullToRefreshBox(isRefreshing=refreshing,onRefresh={refreshing=true;kotlinx.coroutines.GlobalScope.launchWhenever{delay(800);items=List(20){"row $it ${System.currentTimeMillis()%100}"};refreshing=false}}){LazyColumn{items(items){ListItem(headlineContent={Text(it)})}}}}
